// SPDX-License-Identifier: MIT
//! **Byte-exact goldens captured from real `iproute2`.**
//!
//! Every constant below is the complete netlink datagram a stock `tc` binary
//! put on the wire, recovered from a `strace` of the `sendmsg` call and
//! re-encoded byte for byte (the reconstruction is checked against the
//! message's own `nlmsg_len`, so a truncated capture cannot slip through).
//! Each test states the exact command it came from.
//!
//! Capture recipe — every command below was run inside one unprivileged
//! network namespace so nothing touched host state:
//!
//! ```sh
//! unshare -rn strace -f -e trace=sendmsg -xx -s 8192 -e abbrev=none ./commands.sh
//! ```
//!
//! Provenance of the capture host: `iproute2-6.19.0`, Linux 7.0, and
//! `/proc/net/psched` = `000003e8 00000040 000f4240 3b9aca00` (t2us=1000,
//! us2t=64, clock_res=1e6, tfsc=1e9). That psched line is what makes the
//! rate tables and every `buffer`/`burst` tick value reproducible; it is
//! pinned as `ratespec.golden_psched` and passed to every builder here, so
//! these tests are host-independent.
//!
//! `nlmsg_seq` is part of the captured bytes, so each golden carries the
//! sequence number its capture used and hands it to the builder.

const std = @import("std");
const builtin = @import("builtin");
const native_endian = builtin.cpu.arch.endian();

const handle_mod = @import("handle.zig");
const Handle = handle_mod.Handle;
const ratespec = @import("ratespec.zig");
const qdisc = @import("qdisc.zig");
const filter = @import("filter.zig");
const U32Key = filter.U32Key;
const ETH_P = filter.ETH_P;
const IPPROTO = filter.IPPROTO;
const action = @import("action.zig");
const ActionSpec = action.ActionSpec;
const GactWire = action.GactWire;
const PACKET = action.PACKET;
const message = @import("message.zig");

const testing = std.testing;
const gpa = testing.allocator;

/// The capture host's psched calibration (see the module comment).
const ps = ratespec.golden_psched;

/// `lo` is always ifindex 1 in a fresh network namespace, which is what the
/// captures ran in.
const lo: u32 = 1;

/// Compare a built request against a golden hex string, decoding the golden
/// on the fly so the constants stay greppable next to the command that
/// produced them.
fn expectGolden(hex: []const u8, actual: []const u8) !void {
    if (native_endian != .little) return error.SkipZigTest; // captures are LE
    try testing.expectEqual(hex.len / 2, actual.len);
    var expected: [4096]u8 = undefined;
    const want = try std.fmt.hexToBytes(expected[0 .. hex.len / 2], hex);
    try testing.expectEqualSlices(u8, want, actual);
}

