// ── qdisc goldens ───────────────────────────────────────────────────────────

test "golden: htb qdisc add" {
    // tc qdisc add dev lo root handle 1: htb default 10
    // (`default` is parsed base-16 by tc, hence defcls 0x10.)
    const req = try message.buildQdiscSet(
        gpa,
        seq_htb_qdisc_add,
        .add,
        .{ .ifindex = lo, .handle = Handle.init(1, 0), .parent = Handle.root },
        .{ .htb = .{ .defcls = 0x10 } },
        ps,
    );
    defer gpa.free(req);
    try expectGolden(g_htb_qdisc_add, req);
}

test "golden: htb qdisc add with r2q + direct_qlen" {
    // tc qdisc add dev lo root handle 1: htb default 0 r2q 5 direct_qlen 100
    const req = try message.buildQdiscSet(
        gpa,
        seq_htb_qdisc_add_tuned,
        .add,
        .{ .ifindex = lo, .handle = Handle.init(1, 0), .parent = Handle.root },
        .{ .htb = .{ .rate2quantum = 5, .defcls = 0, .direct_qlen = 100 } },
        ps,
    );
    defer gpa.free(req);
    try expectGolden(g_htb_qdisc_add_tuned, req);
}

test "golden: tbf qdisc add (rate table + burst)" {
    // tc qdisc add dev lo root handle 5: tbf rate 1mbit burst 32kbit latency 400ms
    // (tc's `32kbit` is 32 * 1024 / 8 = 4096 bytes; `1mbit` is 125000 B/s.)
    const req = try message.buildQdiscSet(
        gpa,
        seq_tbf_qdisc_add,
        .add,
        .{ .ifindex = lo, .handle = Handle.init(5, 0), .parent = Handle.root },
        .{ .tbf = .{ .rate = 125_000, .burst = 4096, .latency_us = 400_000 } },
        ps,
    );
    defer gpa.free(req);
    try expectGolden(g_tbf_qdisc_add, req);
}

test "golden: tbf qdisc add with a peak bucket (PTAB + PBURST)" {
    // tc qdisc add dev lo root handle 2: tbf rate 10mbit burst 10kb latency 50ms \
    //     peakrate 20mbit mtu 1540
    const req = try message.buildQdiscSet(
        gpa,
        seq_tbf_qdisc_add_peak,
        .add,
        .{ .ifindex = lo, .handle = Handle.init(2, 0), .parent = Handle.root },
        .{ .tbf = .{
            .rate = 1_250_000,
            .burst = 10 * 1024,
            .latency_us = 50_000,
            .peakrate = 2_500_000,
