test "golden: htb class add with a >32-bit rate (RATE64 + CEIL64)" {
    // tc class add dev lo parent 1: classid 1:30 htb rate 40gbit ceil 80gbit
    // 40 Gbit/s = 5e9 B/s > 2^32, so tc clamps tc_ratespec.rate to ~0U and
    // adds TCA_HTB_RATE64; the rate tables stay computed from the clamp.
    const req = try message.buildClassSet(
        gpa,
        seq_htb_class_add_rate64,
        .add,
        .{ .ifindex = lo, .handle = Handle.init(1, 0x30), .parent = Handle.init(1, 0) },
        .{ .htb = .{ .rate = 5_000_000_000, .ceil = 10_000_000_000 } },
        ps,
    );
    defer gpa.free(req);
    try expectGolden(g_htb_class_add_rate64, req);
}

