test "golden: htb class add with a rate in [2^31, 2^32) (F4)" {
    // tc class add dev lo parent 1: classid 1:50 htb rate 20gbit ceil 20gbit
    // (preceded by `tc qdisc add dev lo root handle 1: htb default 1` in the
    // capturing netns, same as every other class golden here.)
    //
    // Wave-3 audit's F4: no golden exercised a rate in this exact band before
    // this one. `clampRate`'s `rate >= (1 << 32)` threshold and the separate
    // `RATE64` decision (`qdisc.zig` ~line 497/668, both keyed off the same
    // bound) are two independent conditions on the SAME constant — a golden
    // at exactly 40gbit/80gbit (`g_htb_class_add_rate64`, already in this
    // file) is comfortably above 2^32 B/s and can't discriminate a mutant
    // that moves the threshold down to `(1 << 31)`; 20gbit/s = 2.5e9 B/s
    // sits inside the band that would newly (and silently) clamp to
    // maxInt(u32) without RATE64 under such a mutant. Captured for real
    // (`unshare -rn strace`, recipe in the module header comment) against
    // stock `iproute2-6.19.0` — not hand-built bytes.
    const req = try message.buildClassSet(
        gpa,
        seq_htb_class_add_band31,
        .add,
        .{ .ifindex = lo, .handle = Handle.init(1, 0x50), .parent = Handle.init(1, 0) },
        .{ .htb = .{ .rate = 2_500_000_000, .ceil = 2_500_000_000 } },
        ps,
    );
    defer gpa.free(req);
    try expectGolden(g_htb_class_add_band31, req);
}

