// ── round-trip: every golden re-parses into the values it encoded ───────────

test "goldens re-parse: htb class, u32 filter, flower filter" {
    const codec = @import("netlink").codec;

    var buf: [4096]u8 = undefined;
    {
        const bytes = try std.fmt.hexToBytes(buf[0 .. g_htb_class_add_rate64.len / 2], g_htb_class_add_rate64);
        var it: codec.MessageIterator = .{ .buf = bytes };
        const m = (try it.next()).?;
        const c = try qdisc.parseClass(m.payload);
        try testing.expectEqualStrings("htb", c.kind());
        try testing.expectEqual(Handle.init(1, 0x30).raw, c.handle.raw);
        const h = c.htb.?;
        try testing.expectEqual(@as(u64, 5_000_000_000), h.rate64);
        try testing.expectEqual(@as(u64, 10_000_000_000), h.ceil64);
        try testing.expectEqual(@as(u32, 6), h.buffer);
        try testing.expectEqual(@as(u32, 3), h.cbuffer);
    }
    {
        const bytes = try std.fmt.hexToBytes(buf[0 .. g_u32_filter_add_two_keys.len / 2], g_u32_filter_add_two_keys);
        var it: codec.MessageIterator = .{ .buf = bytes };
        const m = (try it.next()).?;
        const f = try filter.parseFilter(m.payload);
        try testing.expectEqualStrings("u32", f.kind());
        try testing.expectEqual(@as(u16, 1), f.prio);
        try testing.expectEqual(ETH_P.IP, f.eth_type);
        try testing.expectEqual(Handle.init(1, 0x10).raw, f.classid().?.raw);
        const u = f.u32_sel.?;
        try testing.expectEqual(@as(u8, 2), u.nkeys);
        try testing.expectEqualSlices(u8, &.{ 192, 168, 1, 0 }, &u.keys[0].val);
        try testing.expectEqual(@as(i32, 16), u.keys[1].off);
    }
    {
        const bytes = try std.fmt.hexToBytes(buf[0 .. g_flower_filter_add_v6.len / 2], g_flower_filter_add_v6);
        var it: codec.MessageIterator = .{ .buf = bytes };
        const m = (try it.next()).?;
        const f = try filter.parseFilter(m.payload);
        try testing.expectEqualStrings("flower", f.kind());
        try testing.expectEqual(@as(u16, 4), f.prio);
        try testing.expectEqual(ETH_P.IPV6, f.eth_type);
        const fl = f.flower.?;
        try testing.expectEqual(IPPROTO.UDP, fl.ip_proto.?);
        try testing.expectEqual(@as(u16, 53), fl.dst_port.?);
        try testing.expectEqual(Handle.init(1, 0x30).raw, fl.classid.?.raw);
    }
}

test "goldens re-parse: tbf and fq_codel qdiscs" {
    const codec = @import("netlink").codec;
    var buf: [4096]u8 = undefined;
    {
        const bytes = try std.fmt.hexToBytes(buf[0 .. g_tbf_qdisc_add_peak.len / 2], g_tbf_qdisc_add_peak);
        var it: codec.MessageIterator = .{ .buf = bytes };
        const m = (try it.next()).?;
        const q = try qdisc.parseQdisc(m.payload);
        try testing.expectEqualStrings("tbf", q.kind());
        const t = q.tbf.?;
        try testing.expectEqual(@as(u32, 1_250_000), t.rate.rate);
        try testing.expectEqual(@as(u32, 2_500_000), t.peakrate.rate);
        try testing.expectEqual(@as(u32, 72_740), t.limit);
        try testing.expectEqual(@as(?u32, 10 * 1024), t.burst_bytes);
        try testing.expectEqual(@as(?u32, 1540), t.pburst_bytes);
    }
    {
        const bytes = try std.fmt.hexToBytes(buf[0 .. g_fq_codel_qdisc_add.len / 2], g_fq_codel_qdisc_add);
        var it: codec.MessageIterator = .{ .buf = bytes };
        const m = (try it.next()).?;
        const q = try qdisc.parseQdisc(m.payload);
        try testing.expectEqualStrings("fq_codel", q.kind());
        const f = q.fq_codel.?;
        try testing.expectEqual(@as(?u32, 1200), f.limit);
        try testing.expectEqual(@as(?u32, 1024), f.flows);
        try testing.expectEqual(@as(?u32, 1514), f.quantum);
        try testing.expectEqual(@as(?u32, 100_000), f.interval_us);
        try testing.expectEqual(@as(?u32, 5_000), f.target_us);
    }
    {
        const bytes = try std.fmt.hexToBytes(buf[0 .. g_htb_qdisc_add.len / 2], g_htb_qdisc_add);
        var it: codec.MessageIterator = .{ .buf = bytes };
        const m = (try it.next()).?;
        const q = try qdisc.parseQdisc(m.payload);
        try testing.expectEqualStrings("htb", q.kind());
        const h = q.htb.?;
        try testing.expectEqual(@as(u32, 3), h.version);
        try testing.expectEqual(@as(u32, 10), h.rate2quantum);
        try testing.expectEqual(@as(u32, 0x10), h.defcls);
    }
}

// ── action goldens: gact ────────────────────────────────────────────────────

/// The u32 selector every action golden below hangs off: one `match ip src`
/// key plus `flowid 1:10`, so the goldens differ only in their action list.
fn u32ActionReq(
    seq: u32,
    prio: u16,
    src: [4]u8,
    acts: []const ActionSpec,
) ![]u8 {
    const keys = [_]U32Key{U32Key.ipv4Src(src, 32)};
    return message.buildFilterSetWith(
        gpa,
        seq,
        .add,
        .{ .ifindex = lo, .parent = Handle.init(1, 0), .prio = prio, .eth_type = ETH_P.IP },
        .{ .u32 = .{ .classid = Handle.init(1, 0x10), .keys = &keys, .actions = acts } },
        ps,
    );
}

