test "goldens re-parse: hfsc and red qdiscs" {
    const codec = @import("netlink").codec;
    var buf: [1024]u8 = undefined;
    {
        const bytes = try std.fmt.hexToBytes(buf[0 .. g_hfsc_default_qdisc.len / 2], g_hfsc_default_qdisc);
        var it: codec.MessageIterator = .{ .buf = bytes };
        const q = try qdisc.parseQdisc((try it.next()).?.payload);
        try testing.expectEqualStrings("hfsc", q.kind());
        try testing.expectEqual(@as(u16, 0x10), q.hfsc.?.default_class);
    }
    {
        const bytes = try std.fmt.hexToBytes(buf[0 .. g_red_flags_qdisc.len / 2], g_red_flags_qdisc);
        var it: codec.MessageIterator = .{ .buf = bytes };
        const q = try qdisc.parseQdisc((try it.next()).?.payload);
        try testing.expectEqualStrings("red", q.kind());
        const r = q.red.?;
        try testing.expectEqual(@as(u32, 100_000), r.limit);
        try testing.expectEqual(@as(u32, 10_000), r.qth_min);
        try testing.expectEqual(@as(u32, 30_000), r.qth_max);
        try testing.expectEqual(@as(u8, 4), r.wlog);
        try testing.expectEqual(@as(?u32, 7), r.flags);
        try testing.expect(r.max_p != null);
    }
    // hfsc options shorter than the qopt are skipped.
    try testing.expect(qdisc.parseHfscOptions("\x01") == null);
}

test "red options readback: every field apart, wrong-sized attributes skipped" {
    const codec = @import("netlink").codec;
    var l: std.ArrayList(u8) = .empty;
    defer l.deinit(gpa);
    var parms: [16]u8 = undefined;
    std.mem.writeInt(u32, parms[0..4], 1001, native_endian);
    std.mem.writeInt(u32, parms[4..8], 1002, native_endian);
    std.mem.writeInt(u32, parms[8..12], 1003, native_endian);
    parms[12] = 4;
    parms[13] = 5;
    parms[14] = 6;
    parms[15] = 7;
    try codec.appendAttr(gpa, &l, qdisc.TCA_RED.PARMS, &parms);
    try codec.appendAttrU32(gpa, &l, qdisc.TCA_RED.MAX_P, 99);
    var fl: [8]u8 = undefined;
    std.mem.writeInt(u32, fl[0..4], 3, native_endian);
    std.mem.writeInt(u32, fl[4..8], 15, native_endian);
    try codec.appendAttr(gpa, &l, qdisc.TCA_RED.FLAGS, &fl);
    const w = try qdisc.parseRedOptions(l.items);
    try testing.expectEqual(@as(u32, 1001), w.limit);
    try testing.expectEqual(@as(u32, 1002), w.qth_min);
    try testing.expectEqual(@as(u32, 1003), w.qth_max);
    try testing.expectEqual(@as(u8, 4), w.wlog);
    try testing.expectEqual(@as(u8, 5), w.plog);
    try testing.expectEqual(@as(u8, 6), w.scell_log);
    try testing.expectEqual(@as(u8, 7), w.qopt_flags);
    try testing.expectEqual(@as(?u32, 99), w.max_p);
    try testing.expectEqual(@as(?u32, 3), w.flags);

    // Attributes of the wrong size are skipped, not misread.
    var odd: std.ArrayList(u8) = .empty;
    defer odd.deinit(gpa);
    try codec.appendAttr(gpa, &odd, qdisc.TCA_RED.PARMS, &@as([15]u8, @splat(1)));
    try codec.appendAttr(gpa, &odd, qdisc.TCA_RED.MAX_P, &@as([8]u8, @splat(1)));
    try codec.appendAttr(gpa, &odd, qdisc.TCA_RED.FLAGS, &@as([12]u8, @splat(1)));
    const ow = try qdisc.parseRedOptions(odd.items);
    try testing.expect(ow.limit == 0 and ow.max_p == null and ow.flags == null);
}

// ── action goldens: connmark, csum, sample, tunnel_key, pedit, mpls, nat, ct,
// action flags, skbedit extras, vlan push_eth ───────────────────────────────

/// Encode one action into the standard u32 filter and compare it with the
/// golden; returns the first action decoded back from the golden bytes.
fn actionGolden(comptime hex: []const u8, seq: u32, k: u8, spec: ActionSpec) !action.Action {
    const codec = @import("netlink").codec;
    const req = try u32ActionReq(seq, 100 + @as(u16, k), .{ 10, 0, 2, k }, &.{spec});
    defer gpa.free(req);
    try expectGolden(hex, req);
    var buf: [hex.len / 2]u8 = undefined;
    const bytes = try std.fmt.hexToBytes(&buf, hex);
    var it: codec.MessageIterator = .{ .buf = bytes };
    const m = (try it.next()).?;
    const f = try filter.parseFilter(m.payload);
    try testing.expectEqual(@as(usize, 1), f.actions().len);
    return f.actions()[0];
}

test "golden: u32 + connmark" {
    // tc filter add dev lo parent 1: protocol ip prio 101 u32 match ip src 10.0.2.1/32 flowid 1:10 action connmark zone 5
    const a = try actionGolden(g_u32_connmark, seq_u32_connmark, 1, .{ .connmark = .{ .zone = 5 } });
    try testing.expectEqualStrings("connmark", a.kind());
    try testing.expectEqual(@as(u16, 5), a.ext.?.connmark.zone);
    try testing.expectEqual(action.Verdict.pipe, a.gen.action);
}

