    try testing.expectEqual(@as(?u16, 20), w.src_port_max);
    // tc filter add dev lo parent 1: protocol ip prio 60 flower indev lo
    w = try flowerGolden(g_flower_indev, seq_flower_indev, 60, .{ .eth_type = ETH_P.IP, .indev = "lo" });
